const CompletedJobSchema = z
  .object({
    workspace_id: z.string().exactOptional(),
    id: z.uuid(),
    parent_job: z.uuid().exactOptional(),
    created_by: z.string(),
    created_at: z.iso.datetime({ offset: true }),
    started_at: z.iso.datetime({ offset: true }),
    completed_at: z.iso.datetime({ offset: true }).exactOptional(),
    duration_ms: z.int(),
    success: z.boolean(),
    script_path: z.string().exactOptional(),
    script_hash: z.string().exactOptional(),
    args: ScriptArgsSchema.exactOptional(),
    result: z
      .any()
      .exactOptional()
      .openapi({
        description:
          "For large results, this may be the placeholder string 'WINDMILL_TOO_BIG'.\nUse the completed job result endpoint to retrieve the full result.\n",
      }),
    logs: z.string().exactOptional(),
    deleted: z.boolean().exactOptional(),
    raw_code: z.string().exactOptional(),
    canceled: z.boolean(),
    canceled_by: z.string().exactOptional(),
    canceled_reason: z.string().exactOptional(),
    job_kind: z.enum([
      'script',
      'preview',
      'dependencies',
      'flow',
      'flowdependencies',
      'appdependencies',
      'flowpreview',
      'script_hub',
      'identity',
      'deploymentcallback',
      'singlestepflow',
      'flowscript',
      'flownode',
      'appscript',
      'aiagent',
      'unassigned_script',
      'unassigned_flow',
      'unassigned_singlestepflow',
    ]),
    schedule_path: z.string().exactOptional(),
    permissioned_as: z
      .string()
      .openapi({
        description:
          'The user (u/userfoo) or group (g/groupfoo) whom\nthe execution of this script will be permissioned_as and by extension its DT_TOKEN.\n',
      }),
    flow_status: FlowStatusSchema.exactOptional(),
    workflow_as_code_status: WorkflowStatusSchema.exactOptional(),
    raw_flow: FlowValueSchema.exactOptional(),
    is_flow_step: z.boolean(),
    language: ScriptLangSchema.exactOptional(),
    is_skipped: z.boolean(),
    email: z.string(),
    visible_to_owner: z.boolean(),
    mem_peak: z.int().exactOptional(),
    tag: z.string(),
    priority: z.int().exactOptional(),
    labels: z.array(z.string()).exactOptional(),
    self_wait_time_ms: z.number().exactOptional(),
    aggregate_wait_time_ms: z.number().exactOptional(),
    preprocessed: z.boolean().exactOptional(),
    is_retry: z.boolean().exactOptional(),
    resolved: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'whether this failed or canceled run has been marked as handled' }),
    resolved_by: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'who resolved the failure. Enterprise-only, so also absent for a manual resolution outside enterprise; use resolved_automatically to tell the two apart',
      }),
    resolved_at: z.iso.datetime({ offset: true }).exactOptional(),
    resolution_note: z.string().exactOptional(),
    resolved_automatically: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'true when a succeeding retry resolved this rather than a person. Explicit rather than inferred from an absent resolved_by, which is also absent for a manual resolution outside enterprise',
      }),
    trigger_kind: JobTriggerKindSchema.exactOptional(),
    worker: z.string().exactOptional(),
  })
  .openapi({
    required: [
      'id',
      'created_by',
      'duration_ms',
      'created_at',
      'started_at',
      'success',
      'canceled',
      'job_kind',
      'permissioned_as',
      'is_flow_step',
      'is_skipped',
      'email',
      'visible_to_owner',
      'tag',
    ],
  })
  .openapi('CompletedJob')

