type JobType =
  | (z.infer<typeof CompletedJobSchema> & { type?: 'CompletedJob' })
  | (z.infer<typeof QueuedJobSchema> & { type?: 'QueuedJob' })

type TriggerFilterType =
  | { key: string; value: unknown }
  | { path: string; value: unknown }
  | { any_of: TriggerFilterType[] }
  | { all_of: TriggerFilterType[] }
  | { none_of: TriggerFilterType[] }

const AclTargetDatabaseSchema = z
  .object({ kind: z.literal('database') })
  .openapi({ required: ['kind'] })
  .openapi('AclTargetDatabase')

const AclTargetSchemaSchema = z
  .object({ kind: z.literal('schema'), schema: z.string() })
  .openapi({ required: ['kind', 'schema'] })
  .openapi('AclTargetSchema')

const AclTargetTableSchema = z
  .object({ kind: z.literal('table'), schema: z.string(), table: z.string() })
  .openapi({ required: ['kind', 'schema', 'table'] })
  .openapi('AclTargetTable')

type AclTargetType =
  | z.infer<typeof AclTargetDatabaseSchema>
  | z.infer<typeof AclTargetSchemaSchema>
  | z.infer<typeof AclTargetTableSchema>

const OpenFlowSchema = z
  .object({
    summary: z.string().openapi({ description: 'Short description of what this flow does' }),
    description: z
      .string()
      .exactOptional()
      .openapi({ description: 'Detailed documentation for this flow' }),
    value: FlowValueSchema,
    schema: z
      .object({})
      .exactOptional()
      .openapi({
        description:
          "JSON Schema for flow inputs. Use this to define input parameters, their types, defaults, and validation. For resource inputs, set type to 'object' and format to 'resource-<type>' (e.g., 'resource-stripe')",
      }),
    on_behalf_of_email: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Address of the account the flow runs on behalf of. Derived from on_behalf_of on read; accepted on write, where it is resolved to the account it names.',
      }),
    on_behalf_of: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The flow runs with the permissions of this identity: u/{username}, g/{group}, or a bare email when the username is itself email-shaped. The only stored half of the identity; on_behalf_of_email is derived from it. Omit it when writing and it is resolved from that address instead.',
      }),
  })
  .openapi({
    description:
      'Top-level flow definition containing metadata, configuration, and the flow structure',
    required: ['summary', 'value'],
  })
  .openapi('OpenFlow')

const ExtraPermsSchema = z.record(z.string(), z.boolean()).openapi('ExtraPerms')

const FlowMetadataSchema = z
  .object({
    workspace_id: z.string().exactOptional(),
    path: z.string(),
    edited_by: z.string(),
    edited_at: z.iso.datetime({ offset: true }),
    archived: z.boolean(),
    extra_perms: ExtraPermsSchema,
    starred: z.boolean().exactOptional(),
    draft_only: z.boolean().exactOptional(),
    tag: z.string().exactOptional(),
    ws_error_handler_muted: z.boolean().exactOptional(),
    priority: z.int().exactOptional(),
    dedicated_worker: z.boolean().exactOptional(),
    timeout: z.number().exactOptional(),
    visible_to_runner_only: z.boolean().exactOptional(),
    on_behalf_of_email: z.string().exactOptional(),
    on_behalf_of: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Authorization identity the runnable runs as: u/{username}, g/{group}, or a bare email when the username is itself email-shaped. The only stored half of the identity; on_behalf_of_email is derived from it.',
      }),
    labels: z.array(z.string()).default([]).exactOptional(),
    job_token_scopes: z
      .array(z.string())
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Scopes the token of every job of this runnable is restricted to (domain:action[:resource], e.g. oidc:write). Jobs it starts, flow steps and AI agent tools inherit the restriction. Unset, the job token carries the full permissions of the identity the job runs as; an empty list leaves it no API access beyond its own job.',
      }),
    inherited_labels: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Labels inherited from the parent folder, computed at read time. Read-only — edit them on the folder.\n',
      }),
  })
  .openapi({ required: ['path', 'edited_by', 'edited_at', 'archived', 'extra_perms'] })
  .openapi('FlowMetadata')

type FlowType = z.infer<typeof OpenFlowSchema> &
  z.infer<typeof FlowMetadataSchema> & { lock_error_logs?: string; version_id?: number }

