const RunnableItemSchema = z
  .object({
    type: z.enum(['script', 'flow', 'app', 'agent']),
    path: z.string(),
    summary: z.string().exactOptional(),
    workspace_id: z.string().exactOptional(),
    extra_perms: z.record(z.string(), z.boolean()).exactOptional(),
    starred: z.boolean().exactOptional(),
    archived: z.boolean().exactOptional(),
    is_draft: z.boolean().exactOptional(),
    draft_only: z.boolean().nullable().exactOptional(),
    draft_path: z.string().exactOptional(),
    draft_users: z.array(z.object({})).exactOptional(),
    labels: z.array(z.string()).exactOptional(),
    inherited_labels: z.array(z.string()).exactOptional(),
    ws_error_handler_muted: z.boolean().exactOptional(),
    edited_at: z.iso.datetime({ offset: true }).exactOptional(),
    hash: z
      .string()
      .exactOptional()
      .openapi({ description: 'script version hash as a 16-char hex string' }),
    language: z.string().exactOptional(),
    kind: z.string().exactOptional(),
    auto_kind: z.string().exactOptional(),
    use_codebase: z.boolean().exactOptional(),
    has_deploy_errors: z.boolean().exactOptional(),
    chat_input_enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "flow-only. `chat_input_enabled` of the flow's value, projected so the list can mark flows that open as a chat. Omitted when the value has no such field.",
      }),
    raw_app: z.boolean().exactOptional(),
    execution_mode: z.string().exactOptional(),
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64' }),
    version: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64' }),
    agent_memory: z
      .any()
      .exactOptional()
      .openapi({ description: "agent-only. The agent's `memory` setting." }),
    ws_specific: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'agent-only. Whether the agent is workspace-specific, which keeps it out of deploys to other workspaces.',
      }),
  })
  .openapi({
    description:
      "A row in the merged runnables listing. `type` is the discriminator;\nkind-specific fields (hash/language/kind for scripts, execution_mode/\nversion for apps, agent_memory/ws_specific for agents) are present only\nfor that kind. An agent is an `ai_agent` resource whose description is\nreported as `summary`. `edited_at` is the unified last-updated time (a\nscript's created_at, a flow/app/agent's edit time).\n",
    required: ['type', 'path'],
  })
  .openapi('RunnableItem')

