const ExternalJwtTokenSchema = z
  .object({
    jwt_hash: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    email: z.string(),
    username: z.string(),
    is_admin: z.boolean(),
    is_operator: z.boolean(),
    workspace_id: z.string().exactOptional(),
    label: z.string().exactOptional(),
    scopes: z.array(z.string()).exactOptional(),
    last_used_at: z.iso.datetime({ offset: true }),
  })
  .openapi({
    required: ['jwt_hash', 'email', 'username', 'is_admin', 'is_operator', 'last_used_at'],
  })
  .openapi('ExternalJwtToken')

const GuestUsageSchema = z
  .object({
    available: z.boolean(),
    guest_count: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    window_days: z.int(),
    free_allowance: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    metered: z.boolean(),
    billable_guests: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    guest_seats: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
  })
  .openapi({
    description:
      'Guests are free up to `free_allowance` distinct emails over the trailing `window_days`. Past that an Enterprise plan meters them (`metered`, four guests to one seat: `billable_guests`, `guest_seats`); every other plan and build admits no new email until the count drops. `available` is whether this deployment can have guests at all: false on the shared cloud, where guest access requires a self-hosted or dedicated deployment, and every other field is then moot.',
    required: [
      'available',
      'guest_count',
      'window_days',
      'free_allowance',
      'metered',
      'billable_guests',
      'guest_seats',
    ],
  })
  .openapi('GuestUsage')

