const MainArgSignatureSchema = z
  .object({
    type: z.enum(['Valid', 'Invalid']),
    error: z.string(),
    star_args: z.boolean(),
    star_kwargs: z.boolean().exactOptional(),
    args: z.array(
      z
        .object({
          name: z.string(),
          typ: z.xor([
            z.enum([
              'float',
              'int',
              'bool',
              'email',
              'unknown',
              'bytes',
              'dict',
              'datetime',
              'sql',
            ]),
            z.object({ resource: z.string().nullable() }).openapi({ required: ['resource'] }),
            z.object({ str: z.array(z.string()).nullable() }).openapi({ required: ['str'] }),
            z
              .object({
                object: z
                  .object({
                    name: z.string().exactOptional(),
                    props: z
                      .array(
                        z
                          .object({
                            key: z.string(),
                            typ: z.xor([
                              z.enum([
                                'float',
                                'int',
                                'bool',
                                'email',
                                'unknown',
                                'bytes',
                                'dict',
                                'datetime',
                                'sql',
                              ]),
                              z.object({ str: z.any() }).openapi({ required: ['str'] }),
                            ]),
                          })
                          .openapi({ required: ['key', 'typ'] }),
                      )
                      .exactOptional(),
                  })
                  .openapi({ required: [] }),
              })
              .openapi({ required: ['object'] }),
            z
              .object({
                list: z
                  .xor([
                    z.enum([
                      'float',
                      'int',
                      'bool',
                      'email',
                      'unknown',
                      'bytes',
                      'dict',
                      'datetime',
                      'sql',
                    ]),
                    z.object({ str: z.any() }).openapi({ required: ['str'] }),
                  ])
                  .nullable(),
              })
              .openapi({ required: ['list'] }),
          ]),
          has_default: z.boolean().exactOptional(),
          default: z.any().exactOptional(),
        })
        .openapi({ required: ['name', 'typ'] }),
    ),
    auto_kind: z.string().nullable(),
    has_preprocessor: z.boolean().nullable(),
  })
  .openapi({
    required: [
      'star_args',
      'start_kwargs',
      'args',
      'type',
      'error',
      'auto_kind',
      'has_preprocessor',
    ],
  })
  .openapi('MainArgSignature')

