const WebsocketHeartbeatSchema = z
  .object({
    interval_secs: z
      .int()
      .min(1)
      .openapi({ description: 'Interval in seconds between heartbeat messages' }),
    message: z
      .string()
      .openapi({
        description:
          'Message to send as heartbeat. Use {{state}} as a placeholder for a value extracted from incoming messages (see state_field).',
      }),
    state_field: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Optional. Top-level JSON field to extract from incoming messages. The extracted value replaces {{state}} in the heartbeat message.',
      }),
  })
  .openapi({ required: ['interval_secs', 'message'] })
  .openapi('WebsocketHeartbeat')

const TriggerFilterSchema: z.ZodType<TriggerFilterType> = z
  .lazy(() =>
    z
      .xor([
        z.object({ key: z.string(), value: z.any() }).openapi({ required: ['key', 'value'] }),
        z
          .object({
            path: z
              .string()
              .openapi({
                description:
                  'Dotted path into nested objects, e.g. `a.b.c`. Does not traverse arrays.',
              }),
            value: z.any(),
          })
          .openapi({ required: ['path', 'value'] }),
        z.object({ any_of: z.array(TriggerFilterSchema) }).openapi({ required: ['any_of'] }),
        z.object({ all_of: z.array(TriggerFilterSchema) }).openapi({ required: ['all_of'] }),
        z.object({ none_of: z.array(TriggerFilterSchema) }).openapi({ required: ['none_of'] }),
      ])
      .openapi({
        description:
          'Either a leaf filter, matching a field of the message (parsed as JSON) against a value by equality (or superset, when the value is an object or array) — addressed by `key` for a top-level field or `path` for a dotted path into nested objects — or a group nesting sub-filters under a boolean operator (`none_of` matches when none of its sub-filters do).\n',
      }),
  )
  .openapi('TriggerFilter')

const WebsocketTriggerInitialMessageSchema = z
  .union([
    z.object({ raw_message: z.string() }).openapi({ required: ['raw_message'] }),
    z
      .object({
        runnable_result: z
          .object({ path: z.string(), args: ScriptArgsSchema, is_flow: z.boolean() })
          .openapi({ required: ['path', 'args', 'is_flow'] }),
      })
      .openapi({ required: ['runnable_result'] }),
  ])
  .openapi('WebsocketTriggerInitialMessage')

const WebsocketTriggerSchema = TriggerExtraPropertySchema.and(
  z
    .object({
      url: z
        .string()
        .openapi({
          description:
            'The WebSocket URL to connect to (can be a static URL or computed by a runnable)',
        }),
      server_id: z
        .string()
        .exactOptional()
        .openapi({ description: 'ID of the server currently handling this trigger (internal)' }),
      last_server_ping: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({ description: 'Timestamp of last server heartbeat (internal)' }),
      error: z
        .string()
        .exactOptional()
        .openapi({ description: 'Last error message if the trigger failed' }),
      filters: z
        .array(TriggerFilterSchema)
        .openapi({
          description:
            'Filters to match incoming messages (only matching messages trigger the script). Each entry is either a leaf `{key, value}` (top-level field) or `{path, value}` (dotted path into nested objects), or a group `{any_of: [...]}` / `{all_of: [...]}` / `{none_of: [...]}` nesting more entries. Entries at the top level are combined with `filter_logic`.',
        }),
      filter_logic: z
        .enum(['and', 'or'])
        .default('and')
        .exactOptional()
        .openapi({
          description:
            "Logic to apply when evaluating the top-level filters. 'and' requires all of them to match, 'or' requires any of them to match. Nested `any_of`/`all_of`/`none_of` groups carry their own logic.",
        }),
      initial_messages: z
        .array(WebsocketTriggerInitialMessageSchema)
        .nullable()
        .exactOptional()
        .openapi({
          description:
            'Messages to send immediately after connecting (can be raw strings or computed by runnables)',
        }),
      url_runnable_args: ScriptArgsSchema.nullable()
        .exactOptional()
        .openapi({
          description: 'Arguments to pass to the script/flow that computes the WebSocket URL',
        }),
      can_return_message: z
        .boolean()
        .openapi({
          description:
            'If true, the script can return a message to send back through the WebSocket',
        }),
      can_return_error_result: z
        .boolean()
        .openapi({ description: 'If true, error results are sent back through the WebSocket' }),
      heartbeat: WebsocketHeartbeatSchema.nullable()
        .exactOptional()
        .openapi({ description: 'Optional periodic heartbeat message configuration' }),
      error_handler_path: z
        .string()
        .exactOptional()
        .openapi({
          description:
            'Path to a script to run when the triggered job fails. A bare path, without the script/ or flow/ prefix a schedule error handler takes; it cannot be a flow.',
        }),
      error_handler_args: ScriptArgsSchema.exactOptional().openapi({
        description: 'Arguments to pass to the error handler',
      }),
      retry: RetrySchema.exactOptional().openapi({
        description: 'Retry configuration for failed executions',
      }),
    })
    .openapi({ required: ['url', 'filters', 'can_return_message', 'can_return_error_result'] }),
)
  .openapi({ required: ['url', 'filters', 'can_return_message', 'can_return_error_result'] })
  .openapi('WebsocketTrigger')

