const WorkspaceComparisonSchema = z
  .object({
    all_ahead_items_visible: z
      .boolean()
      .openapi({
        description: 'All items with changes ahead are visible by the user of the request.',
      }),
    all_behind_items_visible: z
      .boolean()
      .openapi({
        description: 'All items with changes behind are visible by the user of the request.',
      }),
    skipped_comparison: z
      .boolean()
      .openapi({
        description:
          'Whether the comparison was skipped. This happens with old forks that where not being kept track of',
      }),
    diffs: z
      .array(WorkspaceItemDiffSchema)
      .openapi({ description: 'List of differences found between workspaces' }),
    summary: CompareSummarySchema.openapi({ description: 'Summary statistics of the comparison' }),
    hidden_ahead: HiddenItemsSummarySchema.openapi({
      description: 'Ahead items excluded from `diffs` because they are not visible to the caller',
    }),
    hidden_behind: HiddenItemsSummarySchema.openapi({
      description: 'Behind items excluded from `diffs` because they are not visible to the caller',
    }),
    full_scan_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'For a pair outside the fork lineage, when its candidate set was last seeded by an explicit full scan. Absent when the pair has never been scanned (an empty `diffs` then says nothing about whether the workspaces agree) or when the pair is a lineage pair, which the tally keeps current.',
      }),
  })
  .openapi({
    required: [
      'all_ahead_items_visible',
      'all_behind_items_visible',
      'skipped_comparison',
      'diffs',
      'summary',
      'hidden_ahead',
      'hidden_behind',
    ],
  })
  .openapi('WorkspaceComparison')

