export const getHealthStatusRoute = createRoute({
  method: 'get',
  path: '/health/status',
  tags: ['health'],
  summary: 'health status',
  description:
    'Health status endpoint. Returns cached health status (database connectivity, worker count).\nCache TTL is fixed at 5 seconds. Use force=true query parameter to bypass cache.\nNote: This endpoint is intentionally different from Kubernetes probes to avoid confusion.\nFor k8s liveness/readiness probes, use /version endpoint.\n',
  operationId: 'getHealthStatus',
  request: {
    query: z.object({
      force: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'force',
            in: 'query',
            description: 'Force a fresh check, bypassing the cache',
            required: false,
            schema: { type: 'boolean', default: false },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'server is healthy or degraded',
      content: { 'application/json': { schema: HealthStatusResponseSchema } },
    },
    503: {
      description: 'server is unhealthy (database unreachable)',
      content: { 'application/json': { schema: HealthStatusResponseSchema } },
    },
  },
  security: [],
})

