export const getGithubAppConnectedRepositoriesRoute = createRoute({
  method: 'get',
  path: '/github_app/connected_repositories',
  tags: ['Git Sync'],
  summary: 'get connected repositories',
  operationId: 'getGlobalConnectedRepositories',
  request: {
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Page number for pagination (default 1)',
            required: false,
            schema: { type: 'integer', default: 1 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'connected repositories',
      content: { 'application/json': { schema: GithubInstallationsSchema } },
    },
  },
})

