export const getSettingsCriticalAlertsRoute = createRoute({
  method: 'get',
  path: '/settings/critical_alerts',
  tags: ['setting'],
  summary: 'Get all critical alerts',
  operationId: 'getCriticalAlerts',
  request: {
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'page',
            schema: {
              type: 'integer',
              default: 1,
              description: 'The page number to retrieve (minimum value is 1)',
            },
            required: false,
          },
          description: 'The page number to retrieve (minimum value is 1)',
        }),
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'page_size',
            schema: {
              type: 'integer',
              default: 10,
              maximum: 100,
              description: 'Number of alerts per page (maximum is 100)',
            },
            required: false,
          },
          description: 'Number of alerts per page (maximum is 100)',
        }),
      acknowledged: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'acknowledged',
            schema: {
              type: 'boolean',
              nullable: true,
              description:
                'Filter by acknowledgment status; true for acknowledged, false for unacknowledged, and omit for all alerts',
            },
            required: false,
          },
          description:
            'Filter by acknowledgment status; true for acknowledged, false for unacknowledged, and omit for all alerts',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved all critical alerts',
      content: {
        'application/json': {
          schema: z
            .object({
              alerts: z.array(CriticalAlertSchema).exactOptional(),
              total_rows: z
                .int()
                .exactOptional()
                .openapi({ description: 'Total number of rows matching the query.', example: 100 }),
              total_pages: z
                .int()
                .exactOptional()
                .openapi({
                  description: 'Total number of pages based on the page size.',
                  example: 10,
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

