export const getSettingsObjectStorageUsageRoute = createRoute({
  method: 'get',
  path: '/settings/object_storage_usage',
  tags: ['setting'],
  summary: 'get current or last object storage usage computation (null if never run)',
  operationId: 'getObjectStorageUsage',
  responses: {
    200: {
      description: 'current or last storage-usage computation state',
      content: {
        'application/json': {
          schema: z
            .object({
              running: z.boolean(),
              started_at: z.iso.datetime({ offset: true }),
              finished_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
              current_prefix: z.string().nullable().exactOptional(),
              scanned_objects: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64' }),
              folders: z.array(
                z
                  .object({
                    prefix: z.string(),
                    size: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64' }),
                    partial: z.boolean().exactOptional(),
                  })
                  .openapi({ required: ['prefix', 'size'] }),
              ),
              error: z.string().nullable().exactOptional(),
            })
            .nullable()
            .openapi({ required: ['running', 'started_at', 'scanned_objects', 'folders'] }),
        },
      },
    },
  },
})

