export const getUsersRefreshTokenRoute = createRoute({
  method: 'get',
  path: '/users/refresh_token',
  tags: ['user'],
  summary: 'refresh the current token',
  operationId: 'refreshUserToken',
  request: {
    query: z.object({
      if_expiring_in_less_than_s: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'if_expiring_in_less_than_s',
            in: 'query',
            required: false,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'new token', content: { 'text/plain': { schema: z.string() } } },
  },
})

