export const deleteWWorkspaceGithubAppInstallationInstallationIdRoute = createRoute({
  method: 'delete',
  path: '/w/{workspace}/github_app/installation/{installation_id}',
  tags: ['Git Sync'],
  summary: 'Delete a GitHub installation from a workspace',
  description:
    'Removes a GitHub installation from the specified workspace. Requires admin privileges.',
  operationId: 'deleteFromWorkspace',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      installation_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'installation_id',
            in: 'path',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            description: 'The ID of the GitHub installation to delete',
          },
        }),
    }),
  },
  responses: { 200: { description: 'Installation successfully deleted' } },
})

export const getWWorkspaceGithubAppExportInstallationIdRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/github_app/export/{installationId}',
  tags: ['Git Sync'],
  summary: 'Export GitHub installation JWT token',
  description: 'Exports the JWT token for a specific GitHub installation in the workspace',
  operationId: 'exportInstallation',
  request: {
    params: z.object({
      workspace: z
        .string()
        .openapi({
          param: { name: 'workspace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      installationId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'installationId',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully exported the JWT token',
      content: {
        'application/json': {
          schema: z.object({ jwt_token: z.string().exactOptional() }).openapi({ required: [] }),
        },
      },
    },
  },
})

