export const getWWorkspaceGitSyncCredentialOriginRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/git_sync/credential/origin',
  tags: ['Git Sync'],
  summary: "Where a repository's credential comes from",
  description:
    "Whether Windmill holds this repository's access token, and which host it talks to. `held` means this workspace stores it, `borrowed` means an ancestor does and it is not this workspace's to replace. Both absent means the repository authenticates with whatever its URL carries. Returns no secret. Requires workspace admin.",
  operationId: 'getCredentialOrigin',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      path: z
        .string()
        .openapi({
          param: {
            name: 'path',
            in: 'query',
            required: true,
            description:
              'Path of the git repository resource, with or without the `$res:` prefix. A path rather than a URL, because a resource URL may carry a token and a URL in a query string lands in logs.',
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'where the credential comes from',
      content: {
        'application/json': {
          schema: z
            .object({
              origin: z.enum(['held', 'borrowed']).exactOptional(),
              provider: z.literal('gitlab').exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

