export const postGithubAppGhesAssignRoute = createRoute({
  method: 'post',
  path: '/github_app/ghes/assign',
  tags: ['Git Sync'],
  summary: 'Assign GHES installation to a workspace',
  description:
    'Assigns a discovered GHES App installation to a workspace. The resulting\ninstallation is marked as admin-provisioned, so workspace admins cannot\nremove it. Super-admin only.\n',
  operationId: 'assignGhesInstallation',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              workspace_id: z.string(),
              installation_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64' }),
            })
            .openapi({ required: ['workspace_id', 'installation_id'] }),
        },
      },
      required: true,
    },
  },
  responses: { 200: { description: 'Installation assigned' } },
})

export const deleteGithubAppGhesAssignWorkspaceIdInstallationIdRoute = createRoute({
  method: 'delete',
  path: '/github_app/ghes/assign/{workspace_id}/{installation_id}',
  tags: ['Git Sync'],
  summary: 'Unassign GHES installation from a workspace',
  description:
    'Removes an installation (admin-provisioned or otherwise) from a\nworkspace. Super-admin only. Does not affect the installation on the\nGitHub side.\n',
  operationId: 'unassignGhesInstallation',
  request: {
    params: z.object({
      workspace_id: z
        .string()
        .openapi({
          param: { name: 'workspace_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
      installation_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'installation_id',
            in: 'path',
            required: true,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
  },
  responses: { 200: { description: 'Installation unassigned' } },
})

