export const postWWorkspaceWorkspacesSeedFullDiffTargetWorkspaceIdRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/workspaces/seed_full_diff/{target_workspace_id}',
  tags: ['workspace'],
  summary: 'Seed the diff candidate set against an arbitrary workspace',
  description:
    'Enumerates every item of both workspaces as an undecided diff candidate so `compareWorkspaces` can compare a pair the fork lineage does not track. Requires being an admin of both workspaces, and is rejected for a pair already linked by the lineage (whose diff is tallied continuously). The comparison itself is what compares the candidates, and is the expensive step.',
  operationId: 'seedFullDiffScan',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      target_workspace_id: z
        .string()
        .openapi({
          param: {
            name: 'target_workspace_id',
            in: 'path',
            required: true,
            schema: { type: 'string' },
            description: 'The ID of the workspace to compare with',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Scan seeded',
      content: {
        'application/json': {
          schema: z
            .object({
              candidates: z
                .int()
                .openapi({ description: 'Number of candidate items the comparison will evaluate' }),
              scanned_at: z.iso.datetime({ offset: true }),
            })
            .openapi({ required: ['candidates', 'scanned_at'] }),
        },
      },
    },
  },
})

