export const postWWorkspaceWorkspacesSettingsDocumentRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/workspaces/settings_document',
  tags: ['workspace'],
  summary: 'apply a workspace settings document',
  description:
    'Applies a settings document, each setting through the endpoint that owns it. Admin only.',
  operationId: 'applyWorkspaceSettingsDocument',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              document: z
                .looseObject({})
                .openapi({
                  description:
                    'The settings to apply, in the layout of the document. A secret given as `__SENSITIVE_AND_UNCHANGED__` keeps its stored value; one prefixed with `$encrypted:` is decrypted with the workspace key.',
                }),
              replace: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Clear the settings `wmill sync push` clears when settings.yaml omits them. Otherwise a setting the document omits is left as it is.',
                }),
              dry_run: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Only compute the changes, without applying them.' }),
            })
            .openapi({ required: ['document'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'the changes, applied unless dry_run',
      content: {
        'application/json': {
          schema: z
            .object({
              changes: z.array(
                z
                  .object({ key: z.string(), before: z.any(), after: z.any() })
                  .openapi({ required: ['key', 'before', 'after'] }),
              ),
              applied: z.boolean(),
              warnings: z.array(z.string()).exactOptional(),
            })
            .openapi({ required: ['changes', 'applied'] }),
        },
      },
    },
  },
})

