export const postWWorkspaceWorkspacesRunDatatableMigrationsDatatableNameRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/workspaces/run_datatable_migrations/{datatable_name}',
  tags: ['workspace'],
  summary: 'run pending datatable migrations against a datatable',
  operationId: 'runDatatableMigrations',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      datatable_name: z
        .string()
        .openapi({
          param: { name: 'datatable_name', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      up_to: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'up_to',
            in: 'query',
            required: false,
            description: 'only apply pending migrations up to and including this version',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      only: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'only',
            in: 'query',
            required: false,
            description: 'apply only this specific migration version, ignoring others',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      schema: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'schema',
            in: 'query',
            required: false,
            description:
              'apply only the pending migrations whose `-- schemas` annotation declares this schema',
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'applied migrations',
      content: {
        'application/json': {
          schema: z
            .object({
              applied: z.array(
                z
                  .object({
                    version: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64' }),
                    name: z.string(),
                  })
                  .openapi({ required: ['version', 'name'] }),
              ),
            })
            .openapi({ required: ['applied'] }),
        },
      },
    },
  },
})

