  createRoute({
    method: 'delete',
    path: '/w/{workspace}/workspaces/delete_datatable_migration/{datatable_name}/{timestamp}',
    tags: ['workspace'],
    summary: 'delete a single datatable migration definition',
    operationId: 'deleteDatatableMigration',
    request: {
      params: z.object({
        workspace: WorkspaceIdParamsSchema,
        datatable_name: z
          .string()
          .openapi({
            param: {
              name: 'datatable_name',
              in: 'path',
              required: true,
              schema: { type: 'string' },
            },
          }),
        timestamp: z
          .preprocess((val) => {
            if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
              return val
            if (/^-?\d+$/.test(val)) return BigInt(val)
            const num = Number(val)
            return Number.isSafeInteger(num) ? BigInt(num) : val
          }, z.int64())
          .openapi({
            param: {
              name: 'timestamp',
              in: 'path',
              required: true,
              schema: { type: 'integer', format: 'int64' },
            },
          }),
      }),
    },
    responses: {
      200: { description: 'status', content: { 'text/plain': { schema: z.string() } } },
    },
  })

export const postWWorkspaceWorkspacesUpsertDatatableMigrationDatatableNameRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/workspaces/upsert_datatable_migration/{datatable_name}',
  tags: ['workspace'],
  summary: 'insert or update a single datatable migration at an explicit version',
  operationId: 'upsertDatatableMigration',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      datatable_name: z
        .string()
        .openapi({
          param: { name: 'datatable_name', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              timestamp: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64' }),
              name: z.string(),
              code_up: z.string(),
              code_down: z.string().exactOptional(),
            })
            .openapi({ required: ['timestamp', 'name', 'code_up'] }),
        },
      },
      required: true,
    },
  },
  responses: { 200: { description: 'status', content: { 'text/plain': { schema: z.string() } } } },
})

