export const postWWorkspaceWorkspacesGetDatatableFullSchemaRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/workspaces/get_datatable_full_schema',
  tags: ['workspace'],
  summary: 'get the full schema of a datatable database as TableEditorValues',
  operationId: 'getDatatableFullSchema',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              source: z
                .string()
                .openapi({ description: "Source datatable, e.g. 'datatable://main'" }),
            })
            .openapi({ required: ['source'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Schema as { schema_name: { table_name: TableEditorValues } }',
      content: {
        'application/json': {
          schema: z.record(
            z.string(),
            z.record(
              z.string(),
              z
                .object({
                  name: z.string(),
                  columns: z.array(
                    z
                      .object({
                        name: z.string(),
                        datatype: z.string(),
                        primary_key: z.boolean().exactOptional(),
                        default_value: z.string().exactOptional(),
                        nullable: z.boolean().exactOptional(),
                      })
                      .openapi({ required: ['name', 'datatype'] }),
                  ),
                  foreign_keys: z.array(
                    z
                      .object({
                        target_table: z.string().exactOptional(),
                        columns: z.array(
                          z
                            .object({
                              source_column: z.string().exactOptional(),
                              target_column: z.string().exactOptional(),
                            })
                            .openapi({ required: [] }),
                        ),
                        on_delete: z.string(),
                        on_update: z.string(),
                        fk_constraint_name: z.string().exactOptional(),
                      })
                      .openapi({ required: ['columns', 'on_delete', 'on_update'] }),
                  ),
                  pk_constraint_name: z.string().exactOptional(),
                })
                .openapi({ required: ['name', 'columns', 'foreign_keys'] }),
            ),
          ),
        },
      },
    },
  },
})

