export const getWWorkspaceUsersListAddableRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/users/list_addable',
  tags: ['user'],
  summary:
    'list instance users that can still be added to this workspace (require to be super admin)',
  operationId: 'listAddableInstanceUsers',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description: 'filter users whose email or username contains this string',
            schema: { type: 'string' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'number of users to return (default 10, max 100)',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'addable instance users',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({ email: z.string(), username: z.string().exactOptional() })
              .openapi({ required: ['email'] }),
          ),
        },
      },
    },
  },
})

