export const getOidcSigningStatusRoute = createRoute({
  method: 'get',
  path: '/oidc/signing_status',
  tags: ['oidc'],
  summary: 'what signs OIDC tokens and the keys the JWKS serves (ee only, superadmin)',
  operationId: 'getOidcSigningStatus',
  responses: {
    200: {
      description: 'OIDC signing status',
      content: {
        'application/json': {
          schema: z
            .object({
              mode: z.enum(['database', 'file', 'external']),
              keys: z.array(
                z
                  .object({
                    kid: z.string().exactOptional(),
                    alg: z.string(),
                    state: z.enum(['pending', 'active', 'retired', 'published']),
                    source: z.enum(['signer', 'database', 'file', 'publish_dir']),
                  })
                  .openapi({ required: ['alg', 'state', 'source'] }),
              ),
              signer: z
                .object({
                  last_refresh_success: z.iso.datetime({ offset: true }).exactOptional(),
                  last_refresh_error: z.string().exactOptional(),
                  breaker: z.enum(['closed', 'open', 'half_open']),
                  max_rps: z.number(),
                  current_rps: z.number(),
                  keys_from_store: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'the keys served are those stored by the last accepted listing, the signer has not answered this server yet',
                    }),
                  tls_files_error: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'why the mTLS files on disk are not the ones in use' }),
                })
                .exactOptional()
                .openapi({
                  description: 'set when an external signer is configured',
                  required: ['breaker', 'max_rps', 'current_rps'],
                }),
            })
            .openapi({ required: ['mode', 'keys'] }),
        },
      },
    },
  },
})

