export const postWWorkspaceDeploymentRequestIdCancelRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/deployment_request/{id}/cancel',
  tags: ['workspace'],
  summary: 'cancel an open deployment request',
  operationId: 'cancelDeploymentRequest',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'cancelled', content: { 'text/plain': { schema: z.string() } } },
  },
})

