export const postWWorkspaceOauthCreateAccountRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/oauth/create_account',
  tags: ['oauth'],
  summary: 'create OAuth account',
  operationId: 'createAccount',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    body: {
      description: 'code endpoint',
      content: {
        'application/json': {
          schema: z
            .object({
              refresh_token: z
                .string()
                .openapi({
                  description:
                    'OAuth refresh token. For authorization_code flow, this contains the actual refresh token. For client_credentials flow, this must be set to an empty string.',
                }),
              expires_in: z.int(),
              client: z.string(),
              grant_type: z.string().default('authorization_code').exactOptional(),
              cc_client_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'OAuth client ID for resource-level credentials (client_credentials flow only)',
                }),
              cc_client_secret: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'OAuth client secret for resource-level credentials (client_credentials flow only)',
                }),
              cc_instance: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Instance name for built-in providers whose client-credentials token URL is instance-templated; substituted into the fixed-host registry template server-side (client_credentials flow only). The token URL is never caller-supplied.',
                }),
              cc_token_url: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Bring-your-own token endpoint override (client_credentials flow only). Only honored together with cc_client_id/cc_client_secret and mutually exclusive with cc_instance; ignored/rejected on the shared-instance path.',
                }),
              mcp_server_url: z
                .string()
                .exactOptional()
                .openapi({ description: 'MCP server URL for MCP OAuth token refresh' }),
              scopes: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'OAuth scopes to use for token refresh. Overrides instance-level scopes.',
                }),
              variable: CreateVariableSchema.exactOptional().openapi({
                description:
                  "The variable holding this account's access token. It is created with the account, in one transaction and with the same checks as createVariable, and linked to it so it refreshes through it.",
              }),
            })
            .openapi({ required: ['refresh_token', 'expires_in', 'client'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: 'account set', content: { 'text/plain': { schema: z.string() } } },
  },
})

