export const getWWorkspaceResourcesHistoryVIdRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/resources/history/v/{id}',
  tags: ['resource'],
  summary: 'get a single resource version, with its value',
  operationId: 'getResourceVersion',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: "The version's id, not its number.",
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'resource version',
      content: {
        'application/json': {
          schema: ResourceVersionSchema.and(
            z
              .object({ value: z.any().exactOptional(), missing_references: z.array(z.string()) })
              .openapi({ required: ['missing_references'] }),
          ),
        },
      },
    },
  },
})

