export const getWWorkspaceResourcesListRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/resources/list',
  tags: ['resource'],
  summary: 'list resources',
  operationId: 'listResource',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      page: PageParamsSchema,
      per_page: PerPageParamsSchema,
      resource_type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'resource_type',
            description: "resource_types to list from, separated by ',',",
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      resource_type_exclude: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'resource_type_exclude',
            description: "resource_types to not list from, separated by ',',",
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      path_start: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path_start',
            description: 'filter resources by path prefix',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path',
            description: 'exact path match filter',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      description: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'description',
            description: 'pattern match filter for description field (case-insensitive)',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      value: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'value',
            description: 'JSONB subset match filter using base64 encoded JSON',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      broad_filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'broad_filter',
            description: 'broad search across multiple fields (case-insensitive substring match)',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      label: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'label',
            description: 'Filter by label',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      include_draft_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_draft_only',
            description:
              'When true, append per-user draft resources whose path has\nno deployed resource. Synthesized rows carry\n`draft_only: true`.\n',
            in: 'query',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      starred_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'starred_only',
            description: 'Only the `ai_agent` resources the caller starred',
            in: 'query',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'resource list',
      content: { 'application/json': { schema: z.array(ListableResourceSchema) } },
    },
  },
})

