export const getWWorkspaceEmbeddingsQueryResourceTypesRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/embeddings/query_resource_types',
  tags: ['resource'],
  summary: 'query resource types by similarity',
  operationId: 'queryResourceTypes',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      text: z
        .string()
        .openapi({
          param: {
            name: 'text',
            description: 'query text',
            in: 'query',
            required: true,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            description: 'query limit',
            in: 'query',
            required: false,
            schema: { type: 'number' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'resource type details',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({ name: z.string(), score: z.number(), schema: z.any().exactOptional() })
              .openapi({ required: ['name', 'score'] }),
          ),
        },
      },
    },
  },
})

