export const getScriptsHubTopRoute = createRoute({
  method: 'get',
  path: '/scripts/hub/top',
  tags: ['script'],
  summary: 'get top hub scripts',
  operationId: 'getTopHubScripts',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            description: 'query limit',
            in: 'query',
            required: false,
            schema: { type: 'number' },
          },
        }),
      app: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'app',
            description: 'query scripts app',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      kind: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'kind',
            description: 'query scripts kind',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'hub scripts list',
      content: {
        'application/json': {
          schema: z
            .object({
              asks: z
                .array(
                  z
                    .object({
                      id: z.number(),
                      ask_id: z.number(),
                      summary: z.string(),
                      description: z.string().nullable().exactOptional(),
                      app: z.string(),
                      version_id: z.number(),
                      kind: HubScriptKindSchema,
                      votes: z.number(),
                      views: z.number(),
                    })
                    .openapi({
                      required: [
                        'id',
                        'ask_id',
                        'summary',
                        'app',
                        'version_id',
                        'kind',
                        'views',
                        'votes',
                      ],
                    }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

