export const getWWorkspaceScriptsListRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/scripts/list',
  tags: ['script'],
  summary: 'list all scripts',
  operationId: 'listScripts',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      page: PageParamsSchema,
      per_page: PerPageParamsSchema,
      order_desc: OrderDescParamsSchema,
      created_by: CreatedByParamsSchema,
      path_start: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path_start',
            description: 'mask to filter matching starting path',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      path_exact: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path_exact',
            description: 'mask to filter exact matching path',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      first_parent_hash: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'first_parent_hash',
            description: 'mask to filter scripts whom first direct parent has exact hash',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      last_parent_hash: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'last_parent_hash',
            description:
              'mask to filter scripts whom last parent in the chain has exact hash.\nBeware that each script stores only a limited number of parents. Hence\nthe last parent hash for a script is not necessarily its top-most parent.\nTo find the top-most parent you will have to jump from last to last hash\n until finding the parent\n',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      parent_hash: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'parent_hash',
            description:
              'is the hash present in the array of stored parent hashes for this script.\nThe same warning applies than for last_parent_hash. A script only store a\nlimited number of direct parent\n',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      show_archived: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'show_archived',
            description:
              '(default false)\nshow only the archived files.\nwhen multiple archived hash share the same path, only the ones with the latest create_at\nare\ned.\n',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      include_without_main: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_without_main',
            description: '(default false)\ninclude scripts without an exported main function\n',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      include_draft_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_draft_only',
            description: '(default false)\ninclude scripts that have no deployed version\n',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      is_template: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'is_template',
            description:
              '(default regardless)\nif true show only the templates\nif false show only the non templates\nif not defined, show all regardless of if the script is a template\n',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      kinds: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'kinds',
            description: '(default regardless)\nscript kinds to filter, split by comma\n',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      starred_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'starred_only',
            description: '(default false)\nshow only the starred items\n',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      with_deployment_msg: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'with_deployment_msg',
            description: '(default false)\ninclude deployment message\n',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      languages: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'languages',
            in: 'query',
            description:
              'Filter to only include scripts written in the given languages.\nAccepts multiple values as a comma-separated list.\n',
            schema: { type: 'string' },
            required: false,
          },
        }),
      without_description: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'without_description',
            in: 'query',
            description:
              '(default false)\nIf true, the description field will be omitted from the response.\n',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      dedicated_worker: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'dedicated_worker',
            in: 'query',
            description:
              '(default regardless)\nIf true, show only scripts with dedicated_worker enabled.\nIf false, show only scripts with dedicated_worker disabled.\n',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      label: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'label',
            in: 'query',
            required: false,
            schema: { type: 'string' },
            description: 'Filter by label',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'All scripts',
      content: {
        'application/json': {
          schema: z.array(
            ScriptSchema.and(
              z
                .object({
                  is_draft: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'True when the authed user has a draft for this\nscript — either no deployed row exists at this\npath (draft-only) or the user saved a per-user\ndraft on top of the deployed row.\n',
                    }),
                  draft_path: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'User-typed path the editor has staged but not\nyet deployed. Surfaced for draft-only rows so\nthe home list can render the meaningful name\ninstead of the autogenerated\n`u/{user}/draft_{uuid}` URL path. Omitted\nwhen unchanged.\n',
                    }),
                  draft_users: z
                    .array(
                      z
                        .object({ username: z.string().nullable().exactOptional() })
                        .openapi({ required: [] }),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        "Workspace users (including the authed user, and\nthe legacy NULL-email row if any) who have a\nper-user draft at this path. Drives the home\npage's user-avatar circles inside the Draft\nbadge. Omitted when no drafts exist.\n",
                    }),
                })
                .openapi({ required: [] }),
            ),
          ),
        },
      },
    },
  },
})

