export const getWWorkspaceDraftsListRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/drafts/list',
  tags: ['draft'],
  summary: 'list every draft the current user has in this workspace, across all kinds',
  operationId: 'listDrafts',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      all_users: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'all_users',
            in: 'query',
            description:
              "List every draft in the workspace (all users), not just the current user's own + legacy rows. Other users' rows come back with `mine=false` (view-only).",
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      compare_to_workspace: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'compare_to_workspace',
            in: 'query',
            description:
              "A fork passes its parent workspace id here to have each row flagged with `unchanged_from_parent`. Ignored unless it is exactly this workspace's parent.",
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: "the user's drafts",
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                kind: UserDraftItemKindSchema,
                path: z.string(),
                summary: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      "Best-effort, read from the draft JSON's `summary` field when the editor shape carries one.",
                  }),
                draft_path: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      "User-typed friendly path from the draft JSON's `draft_path`, when set and different from the storage path (e.g. a never-deployed item parked at `u/{user}/draft_{uuid}`).",
                  }),
                draft_only: z
                  .boolean()
                  .openapi({
                    description:
                      'No deployed counterpart exists at this path — the draft is the whole item.',
                  }),
                legacy_draft: z
                  .boolean()
                  .openapi({
                    description:
                      'The listed draft is a legacy workspace-level row (email NULL) predating the per-user drafts migration. Only true when no per-user draft exists at this path.',
                  }),
                created_at: z.iso.datetime({ offset: true }),
                can_write: z
                  .boolean()
                  .openapi({
                    description:
                      'Whether the current user may deploy/discard this draft (same check the deploy/discard endpoints enforce).',
                  }),
                mine: z
                  .boolean()
                  .openapi({
                    description:
                      "The row belongs to the current user (own draft or the legacy no-owner row) and is therefore actionable. Always true in the default listing; with `all_users=true`, other users' rows are false (view-only).",
                  }),
                unchanged_from_parent: z
                  .boolean()
                  .exactOptional()
                  .openapi({
                    description:
                      "Only present when `compare_to_workspace` was passed. True when this draft is identical to the parent's draft at the same path/kind/owner (cloned in on fork and never edited here).",
                  }),
                draft_users: z
                  .array(
                    z
                      .object({ username: z.string().nullable().exactOptional() })
                      .openapi({ required: [] }),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      "Draft authors at this (path, kind) — the legacy NULL-email row surfaced as a null username.\nPopulated only for the shared full-page-editor kinds (script/flow/app/raw_app); omitted for\ndrawer kinds, which keep their drafts private. Feeds the Draft badge's owner-avatar circles.\n",
                  }),
              })
              .openapi({
                required: [
                  'kind',
                  'path',
                  'draft_only',
                  'legacy_draft',
                  'created_at',
                  'can_write',
                  'mine',
                ],
              }),
          ),
        },
      },
    },
  },
})

