export const postWWorkspaceDraftsUpdateKindPathRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/drafts/update/{kind}/{path}',
  tags: ['draft'],
  summary: "upsert (or clear) the current user's draft at a path",
  operationId: 'updateDraft',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      kind: UserDraftItemKindSchema.openapi({
        param: {
          name: 'kind',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/UserDraftItemKind' },
        },
      }),
      path: ScriptPathParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              value: z
                .any()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Draft content to save. `null` (or omitted) signals a delete — the row is removed under the same conflict rules.',
                }),
              last_sync: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    "Server timestamp of the client's last known sync for this draft. Omit on first save.",
                }),
              force: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Skip the conflict check and overwrite the server copy.' }),
              legacy: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Delete-only. Target the legacy workspace-level row (email NULL) instead of the current user's row. Used to discard a legacy draft from the review page.",
                }),
              created_at: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    "Upsert-only override for the stored creation timestamp. Normal saves omit it (stamped server-side); the localStorage→DB migration passes the draft's original write time so migrated drafts keep their age.",
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'save result',
      content: {
        'application/json': {
          schema: z
            .object({
              status: z.enum(['saved', 'conflict']),
              current_timestamp: z.iso.datetime({ offset: true }),
              path: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '`saved` only, upsert or delete: where the write landed. Differs from the URL path when the item had moved away from it; the editor follows it there. Absent when a delete found nothing to remove and the caller cannot read the path it moved to.',
                }),
            })
            .openapi({ required: ['status', 'current_timestamp'] }),
        },
      },
    },
  },
})

