export const postWWorkspaceJobsRunPPathRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/jobs/run/p/{path}',
  tags: ['job'],
  summary: 'run script by path',
  operationId: 'runScriptByPath',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema, path: ScriptPathParamsSchema }),
    query: z.object({
      scheduled_for: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'scheduled_for',
            description: 'when to schedule this job (leave empty for immediate run)',
            in: 'query',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      scheduled_in_secs: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'scheduled_in_secs',
            description: 'schedule the script to execute in the number of seconds starting now',
            in: 'query',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      skip_preprocessor: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'skip_preprocessor',
            description: 'skip the preprocessor',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      parent_job: ParentJobParamsSchema,
      tag: WorkerTagParamsSchema,
      cache_ttl: CacheTtlParamsSchema,
      job_id: NewJobIdParamsSchema,
      retry: RunRetryParamsSchema,
      invisible_to_owner: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'invisible_to_owner',
            description: 'make the run invisible to the the script owner (default false)',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
    body: {
      description: 'script args',
      content: { 'application/json': { schema: ScriptArgsSchema } },
      required: true,
    },
  },
  responses: {
    201: { description: 'job created', content: { 'text/plain': { schema: z.uuid() } } },
  },
})

