export const getWWorkspaceRunnablesListRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/runnables/list',
  tags: ['script'],
  summary: 'list runnables (scripts, flows, apps, agents) merged, ordered and keyset-paginated',
  operationId: 'listRunnables',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      order_by: z
        .enum(['updated', 'name'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            description: "sort key: 'updated' (default) or 'name'",
            schema: { type: 'string', enum: ['updated', 'name'] },
            required: false,
          },
        }),
      order_desc: OrderDescParamsSchema,
      kinds: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'kinds',
            in: 'query',
            description: 'comma-separated subset of script,flow,app,agent (default all)',
            schema: { type: 'string' },
            required: false,
          },
        }),
      show_archived: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'show_archived',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      include_without_main: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_without_main',
            in: 'query',
            description: 'include library scripts (no runnable main)',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      path_start: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path_start',
            in: 'query',
            description: 'restrict to paths under this prefix',
            schema: { type: 'string' },
            required: false,
          },
        }),
      label: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'label', in: 'query', schema: { type: 'string' }, required: false },
        }),
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            description:
              'case-insensitive fuzzy match on "summary (path)": the query is split into terms on runs of anything but ASCII letters, digits and apostrophes, and each of the first 8 must appear whole and in order, with anything in between. Terms past the 8th are ignored, so an over-long query matches more rows rather than fewer. Omitted or empty filters nothing; a query holding no ASCII-alphanumeric character at all (a lone space, "_", or text in a non-Latin script) yields no terms and matches nothing, mirroring the homepage, whose matcher discards those queries too.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      per_page: PerPageParamsSchema,
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            description: "opaque keyset cursor from a previous page's next_cursor",
            schema: { type: 'string' },
            required: false,
          },
        }),
      include_draft_only: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_draft_only',
            in: 'query',
            description:
              "also list the caller's drafts at paths with no deployed row, sorted and paginated with the deployed ones. Ignored for operators, in the archived view, and under a label filter (a draft carries no labels).",
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'a page of merged, ordered runnables',
      content: {
        'application/json': {
          schema: z
            .object({ items: z.array(RunnableItemSchema), next_cursor: z.string().exactOptional() })
            .openapi({ required: ['items'] }),
        },
      },
    },
  },
})

