export const getWWorkspaceFlowsGetVVersionRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/flows/get/v/{version}',
  tags: ['flow'],
  summary: 'get flow version',
  operationId: 'getFlowVersion',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .openapi({
          param: { name: 'version', in: 'path', required: true, schema: { type: 'number' } },
        }),
    }),
  },
  responses: {
    200: { description: 'flow details', content: { 'application/json': { schema: FlowSchema } } },
  },
})

