export const getWWorkspaceFlowConversationsConversationIdMessagesRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/flow_conversations/{conversation_id}/messages',
  tags: ['flow_conversations'],
  summary: 'list conversation messages',
  operationId: 'listConversationMessages',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      conversation_id: z
        .uuid()
        .openapi({
          param: {
            name: 'conversation_id',
            description: 'conversation id',
            in: 'path',
            required: true,
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    query: z.object({
      page: PageParamsSchema,
      per_page: PerPageParamsSchema,
      after_seq: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'after_seq',
            description: 'Message sequence cursor to fetch only the messages after that cursor',
            in: 'query',
            required: false,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'conversation messages',
      content: { 'application/json': { schema: z.array(FlowConversationMessageSchema) } },
    },
  },
})

