export const getWWorkspaceSharedUiGetRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/shared_ui/get',
  tags: ['workspace'],
  summary: 'get the workspace shared UI folder (full content)',
  operationId: 'getSharedUi',
  request: { params: z.object({ workspace: WorkspaceIdParamsSchema }) },
  responses: {
    200: {
      description: 'shared UI content',
      content: {
        'application/json': {
          schema: z
            .object({
              files: z.record(z.string(), z.string()),
              version: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64' }),
              edited_at: z.iso.datetime({ offset: true }),
              edited_by: z.string(),
            })
            .openapi({ required: ['files', 'version', 'edited_at', 'edited_by'] }),
        },
      },
    },
  },
})

