export const getWWorkspaceAiUsageRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/ai/usage',
  tags: ['ai'],
  summary: 'list aggregated AI token usage',
  operationId: 'listAiUsage',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      days: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(365),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'days',
            in: 'query',
            schema: { type: 'integer', minimum: 1, maximum: 365 },
            required: false,
          },
        }),
      group_by: z
        .enum(['day', 'user', 'model'])
        .exactOptional()
        .openapi({
          param: {
            name: 'group_by',
            in: 'query',
            schema: { type: 'string', enum: ['day', 'user', 'model'] },
            required: false,
          },
        }),
      scope: z
        .enum(['workspace', 'self'])
        .exactOptional()
        .openapi({
          param: {
            name: 'scope',
            in: 'query',
            description: "workspace-wide usage (admin only) or the calling user's own",
            schema: { type: 'string', enum: ['workspace', 'self'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'usage buckets',
      content: {
        'application/json': {
          schema: z
            .object({
              buckets: z.array(AITokenUsageBucketSchema),
              truncated: z
                .boolean()
                .openapi({
                  description:
                    'more buckets matched than were returned, so summing them under-reports',
                }),
            })
            .openapi({ required: ['buckets', 'truncated'] }),
        },
      },
    },
  },
})

