export const postWWorkspaceAppsCreateRawRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/apps/create_raw',
  tags: ['app'],
  summary: 'create app raw',
  operationId: 'createAppRaw',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    body: {
      description: 'new app',
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              app: z
                .object({
                  path: z.string(),
                  value: z.any(),
                  summary: z.string(),
                  policy: z
                    .object({
                      triggerables: z.record(z.string(), z.object({})).exactOptional(),
                      triggerables_v2: z.record(z.string(), z.object({})).exactOptional(),
                      s3_inputs: z
                        .preprocess(
                          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                          z.array(z.object({})),
                        )
                        .exactOptional(),
                      allowed_s3_keys: z
                        .preprocess(
                          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                          z.array(
                            z
                              .object({
                                s3_path: z.string().exactOptional(),
                                resource: z.string().exactOptional(),
                              })
                              .openapi({ required: [] }),
                          ),
                        )
                        .exactOptional(),
                      execution_mode: z
                        .enum(['viewer', 'publisher', 'guest', 'anonymous'])
                        .exactOptional()
                        .openapi({
                          description:
                            "Who may open the app, and who its runnables execute as. Optional, and what omitting it means depends on the operation: creating an app defaults it to `publisher` (runs on behalf of the app's publisher and requires an authenticated viewer), while updating one keeps the mode the app is already deployed under. Neither `anonymous`, which makes the app publicly executable, nor `guest`, which opens it to anyone the identity provider authenticates, is ever assumed. Widening an app to `guest` is gated by the `RestrictGuestAppDeployment` protection rule",
                        }),
                      on_behalf_of: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "The user or group the app runs as in anonymous or publisher mode (e.g. 'u/admin' or 'g/mygroup'). The authority for the app's identity.",
                        }),
                      on_behalf_of_email: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'Address of `on_behalf_of`, written through from it on every save and returned as stored. Optional; when absent it is derived from `on_behalf_of`. Sending it is optional too; it must name the same account as `on_behalf_of`, and a pair that disagrees is rejected.',
                        }),
                      sandbox: z
                        .preprocess(
                          ((read) => (val: unknown) => {
                            const result = read.safeParse(val)
                            return result.success ? result.data : val
                          })(z.stringbool()),
                          z.boolean(),
                        )
                        .exactOptional()
                        .openapi({
                          description:
                            "Publisher opt-in to app sandbox isolation (alpha). When true the app is isolated from each viewer's Windmill session. When false/absent the app runs same-origin with the viewer's full session (the default, pre-isolation behavior).\n",
                        }),
                      frontend_sdk_scopes: z
                        .preprocess(
                          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                          z.array(z.string()),
                        )
                        .exactOptional()
                        .openapi({
                          description:
                            "Raw apps: author-declared scopes for the frontend SDK token. Takes effect only when `sandbox` is also true — an unsandboxed bundle runs with the viewer's own session, so no token is advertised or minted for it and this list stays inert. On a sandboxed app a non-empty list lets viewers mint (after consenting) a short-lived token carrying their own identity restricted to these scopes, handed to the app bundle so `windmill-client` calls run as the viewer. Must be a subset of the server's curated allowlist (jobs:run, jobs:read, users:read, resources:read, variables:read, flow_conversations:read, flow_conversations:write). Every such token can call whoami without consent, whether `users:read` is declared or not.\n",
                        }),
                    })
                    .openapi({ required: [] }),
                  deployment_message: z.string().exactOptional(),
                  custom_path: z.string().exactOptional(),
                  preserve_on_behalf_of: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        "When true and the caller is a member of the 'wm_deployers' group, preserves the original on_behalf_of value in the policy instead of overwriting it.",
                    }),
                  labels: z
                    .preprocess(
                      (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                      z.array(z.string()),
                    )
                    .exactOptional(),
                  skip_draft_deletion: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'When true (set by the CLI / git sync), deploying this app does not delete an existing user draft at the same path.',
                    }),
                })
                .exactOptional()
                .openapi({ required: ['path', 'value', 'summary', 'policy'] }),
              js: z.string().exactOptional(),
              css: z.string().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: { description: 'app created', content: { 'text/plain': { schema: z.string() } } },
  },
})

