export const postWWorkspaceAppsSignS3ObjectsRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/apps/sign_s3_objects',
  tags: ['app'],
  summary:
    'sign s3 objects (caller must have S3 read permission on each key); the signed URLs can then be used by anonymous users in public apps',
  operationId: 'signS3Objects',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    body: {
      description: 's3 objects to sign',
      content: {
        'application/json': {
          schema: z
            .object({
              s3_objects: z.array(S3ObjectSchema),
              expiry_secs: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  description:
                    'how long the signature stays valid, in seconds. Defaults to 43200 (12h) and is clamped server-side to [60, 604800] (1 minute to 7 days).',
                }),
            })
            .openapi({ required: ['s3_objects'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'signed s3 objects',
      content: { 'application/json': { schema: z.array(S3ObjectSchema) } },
    },
  },
})

