export const postWWorkspaceJobsRestartFIdRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/jobs/restart/f/{id}',
  tags: ['job'],
  summary: 'restart a completed flow at a given step',
  operationId: 'restartFlowAtStep',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema, id: JobIdParamsSchema }),
    query: z.object({
      scheduled_for: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'scheduled_for',
            description: 'when to schedule this job (leave empty for immediate run)',
            in: 'query',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      scheduled_in_secs: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'scheduled_in_secs',
            description: 'schedule the script to execute in the number of seconds starting now',
            in: 'query',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      parent_job: ParentJobParamsSchema,
      tag: WorkerTagParamsSchema,
      job_id: NewJobIdParamsSchema,
      include_header: IncludeHeaderParamsSchema,
      invisible_to_owner: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'invisible_to_owner',
            description: 'make the run invisible to the the flow owner (default false)',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
    body: {
      description: 'restart flow parameters',
      content: {
        'application/json': {
          schema: z
            .object({
              step_id: z
                .string()
                .openapi({
                  description:
                    'top-level step id to restart the flow from (or the outermost container when restarting at a nested step)',
                }),
              branch_or_iteration_n: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'for branchall or loop at the top level, the iteration at which the flow should restart (optional)',
                }),
              flow_version: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'specific flow version to use for restart (optional, uses current version if not specified)',
                }),
              nested_path: z
                .array(
                  z
                    .object({
                      step_id: z.string().openapi({ description: 'step id at this nesting level' }),
                      branch_or_iteration_n: z
                        .int()
                        .exactOptional()
                        .openapi({
                          description:
                            'for ForLoop containers, the iteration to restart at (0-based; iterations 0..n-1 are preserved)',
                        }),
                    })
                    .openapi({ required: ['step_id'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    "path of additional steps to descend into AFTER `step_id`. Each entry represents one level of nesting inside the spawned child of the previous level's container (BranchOne / sequential ForLoop iteration / Subflow). When non-empty, the actual restart point is the LAST entry's step_id.",
                }),
            })
            .openapi({ required: ['step_id'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: { description: 'job created', content: { 'text/plain': { schema: z.uuid() } } },
  },
})

