export const getWWorkspaceJobsCompletedCountJobsRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/jobs/completed/count_jobs',
  tags: ['job'],
  summary: 'count number of completed jobs with filter',
  operationId: 'countCompletedJobs',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      completed_after_s_ago: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'completed_after_s_ago',
            in: 'query',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      success: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { name: 'success', in: 'query', schema: { type: 'boolean' }, required: false },
        }),
      tags: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'tags', in: 'query', schema: { type: 'string' }, required: false },
        }),
      all_workspaces: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'all_workspaces',
            in: 'query',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Count of completed jobs',
      content: { 'application/json': { schema: z.int() } },
    },
  },
})

