export const getWWorkspaceJobsUGetFlowAllResultsIdRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/jobs_u/get_flow_all_results/{id}',
  tags: ['job'],
  summary: "get statuses and truncated results for all jobs of a flow job's execution tree",
  operationId: 'getFlowAllResults',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema, id: JobIdParamsSchema }),
    query: z.object({
      max_result_len: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'max_result_len',
            in: 'query',
            description:
              'per-entry cap (in characters of JSON text) on result_prefix (default 2000, max 30000)',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      step: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'step',
            in: 'query',
            description:
              'step address to resolve to a single job instead of enumerating the tree: "b", "b/c", "b[12]" (1-based iteration/branch), composable as "b[12]/c"',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        "per-job statuses and truncated results of the flow's execution tree, or the single resolved entry when step is provided",
      content: {
        'application/json': {
          schema: z
            .object({
              enclosing_job: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    'set when the requested job is itself a step of a larger flow run; id of the flow run directly enclosing it',
                }),
              entries: z.array(
                z
                  .object({
                    job_id: z.string(),
                    label: z
                      .string()
                      .openapi({
                        description:
                          "human-readable label describing the job's position in the flow tree",
                      }),
                    kind: z
                      .string()
                      .openapi({ description: 'job kind (script, flow, forloopflow, ...)' }),
                    flow_step_id: z.string().nullable().exactOptional(),
                    step_path: z
                      .string()
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'materialized step path (e.g. "a/b")' }),
                    depth: z
                      .int()
                      .openapi({ description: 'depth in the flow tree (0 for the root flow job)' }),
                    parent_module_type: z
                      .string()
                      .nullable()
                      .exactOptional()
                      .openapi({ description: 'parent module type (forloopflow, branchall, ...)' }),
                    sibling_index: z
                      .int()
                      .openapi({
                        description:
                          '1-based index of this job among siblings sharing the same step',
                      }),
                    sibling_count: z
                      .int()
                      .openapi({ description: 'total number of siblings sharing the same step' }),
                    status: z.enum([
                      'success',
                      'failure',
                      'canceled',
                      'skipped',
                      'suspended',
                      'running',
                      'queued',
                    ]),
                    success: z.boolean().exactOptional(),
                    duration_ms: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .exactOptional()
                      .openapi({ type: 'integer', format: 'int64' }),
                    started_at: z.iso.datetime({ offset: true }).exactOptional(),
                    result_prefix: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'result JSON text truncated to the per-entry budget; absent until the job has completed',
                      }),
                    result_length: z
                      .int()
                      .exactOptional()
                      .openapi({
                        description:
                          'full length in characters of the result JSON text (greater than the prefix length when truncated)',
                      }),
                  })
                  .openapi({
                    required: [
                      'job_id',
                      'label',
                      'kind',
                      'depth',
                      'sibling_index',
                      'sibling_count',
                      'status',
                    ],
                  }),
              ),
              truncated: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'true when the tree has more jobs than the entry cap; entries then hold the depth-first prefix',
                }),
              scope_filtered: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "true when the caller's token is tag-scoped; steps running on other tags are omitted",
                }),
              step_error: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'set when step was provided but could not be resolved; a diagnostic listing available step ids or iteration statuses',
                }),
            })
            .openapi({ required: ['entries'] }),
        },
      },
    },
  },
})

