export const getWWorkspaceJobsUDispatchEventsIdRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/jobs_u/dispatch_events/{id}',
  tags: ['job'],
  summary: 'list asset-trigger dispatch events for a producer job',
  description:
    "Returns the chronological log of decisions the asset-trigger dispatcher made after this producer job completed. Each row is one (subscriber, asset write) decision: `dispatched` (with `child_job_id`), `join_pending` (with `received_inputs` / `required_inputs` / `partition`), or `skipped` (with `reason`). Rows are reaped automatically when the producer's `v2_job` row is deleted by the retention sweep.\n",
  operationId: 'listDispatchEvents',
  request: { params: z.object({ workspace: WorkspaceIdParamsSchema, id: JobIdParamsSchema }) },
  responses: {
    200: {
      description: 'dispatch events for this producer job',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                subscriber_path: z.string(),
                asset_kind: z.enum([
                  's3object',
                  'resource',
                  'variable',
                  'ducklake',
                  'datatable',
                  'volume',
                  'dbt',
                ]),
                asset_path: z.string(),
                outcome: z.enum(['dispatched', 'join_pending', 'skipped']),
                child_job_id: z.uuid().exactOptional(),
                partition: z.string().exactOptional(),
                received_inputs: z.int().exactOptional(),
                required_inputs: z.int().exactOptional(),
                debounce_s: z.int().exactOptional(),
                reason: z.string().exactOptional(),
                created_at: z.iso.datetime({ offset: true }),
              })
              .openapi({
                required: ['subscriber_path', 'asset_kind', 'asset_path', 'outcome', 'created_at'],
              }),
          ),
        },
      },
    },
  },
})

export const getWWorkspaceJobsAssetDispatchEdgesRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/jobs/asset_dispatch_edges',
  tags: ['job'],
  summary: 'list asset-cascade producer→child job edges for a folder',
  description:
    "Returns the `dispatched` asset-trigger edges (producer job → child job) whose subscriber lives under `path_start`. Lets a pipeline view reconstruct the cascade tree of a folder by job id and group connected runs. Visibility follows the producer job's RLS.\n",
  operationId: 'listAssetDispatchEdges',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      path_start: z
        .string()
        .openapi({
          param: {
            name: 'path_start',
            in: 'query',
            required: true,
            description: 'Folder path prefix the children live under, e.g. `f/orders/`.',
            schema: { type: 'string' },
          },
        }),
      created_after: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'created_after',
            in: 'query',
            required: false,
            description: 'Only edges dispatched at/after this instant.',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'asset-cascade edges for the folder',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                producer_job_id: z.uuid(),
                child_job_id: z
                  .uuid()
                  .exactOptional()
                  .openapi({
                    description: 'Set for `dispatched`; absent for `join_pending` inputs.',
                  }),
                subscriber_path: z.string(),
                outcome: z.enum(['dispatched', 'join_pending']),
                asset_kind: z.enum([
                  's3object',
                  'resource',
                  'variable',
                  'ducklake',
                  'datatable',
                  'volume',
                  'dbt',
                ]),
                asset_path: z.string(),
                created_at: z.iso.datetime({ offset: true }),
              })
              .openapi({
                required: [
                  'producer_job_id',
                  'subscriber_path',
                  'outcome',
                  'asset_kind',
                  'asset_path',
                  'created_at',
                ],
              }),
          ),
        },
      },
    },
  },
})

