export const postWWorkspaceJobsCompletedResolveRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/jobs/completed/resolve',
  tags: ['job'],
  summary: 'mark failed or canceled jobs as resolved',
  description:
    'Marks failed or canceled jobs as handled so triage surfaces stop showing them as unhandled. The job status itself is unchanged. Returns the ids actually resolved: ids that are not visible to the caller or neither failed nor were canceled are silently skipped.',
  operationId: 'resolveCompletedJobs',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              job_ids: z.array(z.uuid()).max(1000),
              note: z
                .string()
                .max(2000)
                .exactOptional()
                .openapi({
                  description:
                    "a person's explanation of why the failure is considered handled. Enterprise-only: ignored outside enterprise",
                }),
              superseded_by: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    "id of a later successful run of the same runnable that supersedes the failure. Verified server-side, and the resulting note is the server's own wording, so it is recorded regardless of licence. A claim that cannot be verified resolves nothing",
                }),
            })
            .openapi({ required: ['job_ids'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'ids of the jobs that were resolved',
      content: { 'application/json': { schema: z.array(z.uuid()) } },
    },
  },
})

