export const postNativeTriggersServiceNameWWorkspaceIdWebhookInternalIdRoute = createRoute({
  method: 'post',
  path: '/native_triggers/{service_name}/w/{workspace_id}/webhook/{internal_id}',
  tags: ['native_trigger'],
  summary: 'receive webhook from external native trigger service',
  operationId: 'nativeTriggerWebhook',
  request: {
    params: z.object({
      service_name: NativeServiceNameSchema.openapi({
        param: {
          name: 'service_name',
          in: 'path',
          required: true,
          schema: { $ref: '#/components/schemas/NativeServiceName' },
        },
      }),
      workspace_id: z
        .string()
        .openapi({
          param: { name: 'workspace_id', in: 'path', required: true, schema: { type: 'string' } },
        }),
      internal_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'internal_id',
            in: 'path',
            required: true,
            schema: { type: 'integer', format: 'int64' },
            description: 'The internal database ID of the trigger',
          },
        }),
    }),
    body: {
      description: 'webhook payload from external service',
      content: {
        'application/json': { schema: z.looseObject({}) },
        'text/plain': { schema: z.string() },
      },
    },
  },
  responses: {
    200: {
      description: 'webhook received successfully',
      content: { 'text/plain': { schema: z.string() } },
    },
  },
})

