export const getWorkersListRoute = createRoute({
  method: 'get',
  path: '/workers/list',
  tags: ['worker'],
  summary: 'list workers',
  operationId: 'listWorkers',
  request: {
    query: z.object({
      page: PageParamsSchema,
      per_page: PerPageParamsSchema,
      ping_since: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ping_since',
            in: 'query',
            required: false,
            description:
              'number of seconds the worker must have had a last ping more recent of (default to 300)',
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'a list of workers',
      content: { 'application/json': { schema: z.array(WorkerPingSchema) } },
    },
  },
})

