export const getWorkersRunnableStatsRoute = createRoute({
  method: 'get',
  path: '/workers/runnable_stats',
  tags: ['worker'],
  summary:
    'get resource usage per runnable and worker group over a time window (require devops role)',
  operationId: 'getRunnableStats',
  request: {
    query: z.object({
      window_secs: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'window_secs',
            in: 'query',
            required: false,
            description:
              'how far back to read, in seconds (defaults to one day, capped at the 30-day retention)',
            schema: { type: 'integer' },
          },
        }),
      worker_group: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'worker_group',
            in: 'query',
            required: false,
            description: 'only the jobs run by this worker group',
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'workspace',
            in: 'query',
            required: false,
            description: 'only the jobs of this workspace',
            schema: { type: 'string' },
          },
        }),
      order_by: z
        .enum(['total_duration', 'max_memory', 'cpu'])
        .exactOptional()
        .openapi({
          param: {
            name: 'order_by',
            in: 'query',
            required: false,
            description: 'what the rows are ranked by, descending (default: total_duration)',
            schema: { type: 'string', enum: ['total_duration', 'max_memory', 'cpu'] },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            required: false,
            description: 'number of rows to return (default 100, at most 1000)',
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'resource usage per runnable and worker group, heaviest first',
      content: { 'application/json': { schema: z.array(RunnableStatsSchema) } },
    },
  },
})

export const getWorkersQueueMetricsSeriesRoute = createRoute({
  method: 'get',
  path: '/workers/queue_metrics_series',
  tags: ['worker'],
  summary: 'get the queue metrics of a time window, as a bounded line per tag',
  operationId: 'getQueueMetricsSeries',
  request: {
    query: z.object({
      window_secs: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'window_secs',
            in: 'query',
            required: false,
            description:
              'how far back to read, in seconds (defaults to one day, capped at the 14-day retention)',
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'jobs waiting and queue delay per tag, as the vertices of lines joined by straight segments',
      content: {
        'application/json': {
          schema: z
            .object({
              from: z.int().openapi({ description: 'start of the window, in epoch milliseconds' }),
              to: z.int().openapi({ description: 'end of the window, in epoch milliseconds' }),
              tags: z.array(
                z
                  .object({
                    tag: z.string(),
                    count: z
                      .array(z.array(z.number()))
                      .openapi({
                        description: '[epoch ms, jobs waiting more than 3 seconds] vertices',
                      }),
                    delay: z
                      .array(z.array(z.number()))
                      .openapi({
                        description: '[epoch ms, seconds the next job has waited] vertices',
                      }),
                  })
                  .openapi({ required: ['tag', 'count', 'delay'] }),
              ),
            })
            .openapi({ required: ['from', 'to', 'tags'] }),
        },
      },
    },
  },
})

