export const getWWorkspaceCaptureIdRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/capture/{id}',
  tags: ['capture'],
  summary: 'get a capture',
  operationId: 'getCapture',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { name: 'id', in: 'path', required: true, schema: { type: 'integer' } },
        }),
    }),
  },
  responses: {
    200: { description: 'capture', content: { 'application/json': { schema: CaptureSchema } } },
  },
})

