export const getWWorkspaceAssetsListRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/assets/list',
  tags: ['asset'],
  summary: 'List all assets in the workspace with cursor pagination',
  operationId: 'listAssets',
  request: {
    params: z.object({ workspace: WorkspaceIdParamsSchema }),
    query: z.object({
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(1000),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Number of items per page (max 1000, default 50)',
            schema: { type: 'integer', default: 50, minimum: 1, maximum: 1000 },
            required: false,
          },
        }),
      cursor_created_at: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor_created_at',
            in: 'query',
            description:
              'Cursor timestamp for pagination (created_at of last item from previous page)',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      cursor_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor_id',
            in: 'query',
            description: 'Cursor ID for pagination (id of last item from previous page)',
            schema: { type: 'integer', format: 'int64' },
            required: false,
          },
        }),
      asset_path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'asset_path',
            in: 'query',
            description: 'Filter by asset path (case-insensitive partial match)',
            schema: { type: 'string' },
            required: false,
          },
        }),
      usage_path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'usage_path',
            in: 'query',
            description: 'Filter by usage path (case-insensitive partial match)',
            schema: { type: 'string' },
            required: false,
          },
        }),
      asset_kinds: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'asset_kinds',
            in: 'query',
            description: 'Filter by asset kinds (multiple values allowed)',
            schema: { type: 'string' },
            required: false,
          },
        }),
      path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path',
            in: 'query',
            description: 'exact path match filter',
            schema: { type: 'string' },
            required: false,
          },
        }),
      columns: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'columns',
            in: 'query',
            description: 'JSONB subset match filter for columns using base64 encoded JSON',
            schema: { type: 'string' },
            required: false,
          },
        }),
      broad_filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'broad_filter',
            description: 'broad search across multiple fields (case-insensitive substring match)',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'paginated assets in the workspace',
      content: {
        'application/json': {
          schema: z
            .object({
              assets: z.array(
                z
                  .object({
                    path: z.string(),
                    kind: AssetKindSchema,
                    usages: z.array(
                      z
                        .object({
                          path: z.string(),
                          kind: AssetUsageKindSchema,
                          access_type: AssetUsageAccessTypeSchema.exactOptional(),
                          columns: z
                            .record(z.string(), AssetUsageAccessTypeSchema)
                            .exactOptional()
                            .openapi({ description: 'The columns used (for tables)' }),
                          created_at: z.iso
                            .datetime({ offset: true })
                            .exactOptional()
                            .openapi({ description: 'When the asset was detected' }),
                          metadata: z
                            .object({
                              runnable_path: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    "The path of the script/flow that was run (only present when kind is 'job')",
                                }),
                              job_kind: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    "The kind of job (script, flow, preview, etc.) (only present when kind is 'job')",
                                }),
                            })
                            .exactOptional()
                            .openapi({ required: [] }),
                        })
                        .openapi({ required: ['path', 'kind'] }),
                    ),
                    metadata: z
                      .object({
                        resource_type: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              "The type of the resource (only present when kind is 'resource')",
                          }),
                      })
                      .exactOptional()
                      .openapi({ required: [] }),
                  })
                  .openapi({ required: ['path', 'kind', 'usages'] }),
              ),
              next_cursor: z
                .object({
                  created_at: z.iso
                    .datetime({ offset: true })
                    .exactOptional()
                    .openapi({ description: 'Timestamp to use for next page' }),
                  id: z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .exactOptional()
                    .openapi({
                      type: 'integer',
                      format: 'int64',
                      description: 'ID to use for next page',
                    }),
                })
                .nullable()
                .exactOptional()
                .openapi({
                  description: 'Cursor for the next page (null if no more pages)',
                  required: [],
                }),
            })
            .openapi({ required: ['assets'] }),
        },
      },
    },
  },
})

