export const postWWorkspaceHubRawAppsIdRecordingRoute = createRoute({
  method: 'post',
  path: '/w/{workspace}/hub/raw_apps/{id}/recording',
  tags: ['hubPublish'],
  summary: 'attach a recorded session to a hub raw app',
  description:
    "Requires the caller to be a workspace admin. Forwards the request to the\nconfigured Hub scoped to the `{workspace}:{folder}` source and returns\nthe Hub's status code and raw response body.\n",
  operationId: 'publishHubRawAppRecording',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: 'hub id of the raw app',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
    }),
    query: z.object({ folder: HubPublishFolderParamsSchema }),
    body: { content: { 'application/json': { schema: RecordingBodySchema } }, required: true },
  },
  responses: {
    200: {
      description: 'raw Hub response body (status code is passed through from the Hub)',
      content: { 'text/plain': { schema: z.string() } },
    },
  },
})

