export const getWWorkspaceHubProjectsSlugExportRoute = createRoute({
  method: 'get',
  path: '/w/{workspace}/hub/projects/{slug}/export',
  tags: ['hubPublish'],
  summary: 'export a hub project',
  description:
    "Requires the caller to be a workspace admin. Forwards the request to the\nconfigured Hub and returns the Hub's status code and raw response body.\nThe folder scope is only needed to re-export the caller's own draft;\napproved projects are public, so it is optional here.\n",
  operationId: 'getHubProjectExport',
  request: {
    params: z.object({
      workspace: WorkspaceIdParamsSchema,
      slug: z
        .string()
        .regex(/^[a-z0-9][a-z0-9-]*[a-z0-9]$/)
        .min(3)
        .max(50)
        .openapi({
          param: {
            name: 'slug',
            in: 'path',
            required: true,
            description:
              'hub project slug (3-50 chars, lowercase alphanumeric and hyphens, no leading/trailing hyphen)',
            schema: {
              type: 'string',
              minLength: 3,
              maxLength: 50,
              pattern: '^[a-z0-9][a-z0-9-]*[a-z0-9]$',
            },
          },
        }),
    }),
    query: z.object({
      folder: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'folder',
            in: 'query',
            required: false,
            description: 'folder scoping the Hub project source (`{workspace}:{folder}`)',
            schema: { type: 'string' },
          },
        }),
      version: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'version',
            in: 'query',
            required: false,
            description:
              "id of a reviewed project version to export instead of the current one (see the hub's `/projects/{slug}/versions`)",
            schema: { type: 'integer', minimum: 1 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'raw Hub response body (status code is passed through from the Hub)',
      content: { 'text/plain': { schema: z.string() } },
    },
  },
})

